        Set<Integer> allIndexes = new Set<Integer>();
        Set<Integer> noIndexes = new Set<Integer>();
        for (Integer i = 0; i < 200; i++) {
            Id ownerId = Math.mod(i, 2) == 0 ? alternateOwner : currentOwner;
            records.add(makeOpportunity(i, stages[0], null, ownerId));
            allIndexes.add(i);
        }

        Test.startTest();

        // An entirely non-won insertion must have no handover side effects.
        Map<Id, Task> tasks = saveAndAssert(
            records, true, noIndexes, 0, new Map<Id, Task>()
        );

        // Exercise 200 newly won updates with no account IDs at all.
        for (Opportunity record : records) {
            record.StageName = WON;
            record.NextStep = 'Before first win';
        }
        tasks = saveAndAssert(records, false, allIndexes, 0, tasks);

        // Remaining won must not overwrite user edits or recreate/update tasks.
        for (Integer i = 0; i < records.size(); i++) {
            records[i].NextStep = Math.mod(i, 2) == 0 ? null : 'Still won edit ' + i;
            records[i].OwnerId = Math.mod(i, 2) == 0 ? currentOwner : alternateOwner;
            records[i].CloseDate = records[i].CloseDate.addDays(30);
            records[i].Name += ' still won';
        }
        tasks = saveAndAssert(records, false, noIndexes, 0, tasks);

        // Leaving won is not a handover event.
        for (Integer i = 0; i < records.size(); i++) {
            records[i].StageName = stages[1];
            records[i].NextStep = Math.mod(i, 2) == 0 ? 'Reopened step ' + i : null;
        }
        tasks = saveAndAssert(records, false, noIndexes, 0, tasks);

        // Winning again creates another task using the current owner and date,
        // even though the opportunity already has a handover task.
        for (Opportunity record : records) {
            record.StageName = WON;
            record.CloseDate = record.CloseDate.addDays(17);
            record.NextStep = 'Before second win';
        }
        tasks = saveAndAssert(records, false, allIndexes, 0, tasks);

        Test.stopTest();

        Assert.areEqual(
            400, tasks.size(), 'Each opportunity must have two handover tasks.'
        );
    }
