// System context is intentional: retention applies to all integration logs.
public without sharing class LogPurgeJob
    implements Schedulable, Database.Batchable<SObject> {

    private Datetime retentionTime;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        retentionTime = System.now();

        Integer availableDmlRows =
            Limits.getLimitDmlRows() - Limits.getDmlRows();
        Integer availableQueryRows =
            Limits.getLimitQueryRows() - Limits.getQueryRows();
        Integer probeSize = availableDmlRows + 1;

        if (probeSize > availableQueryRows) {
            Database.executeBatch(this, 200);
            return;
        }

        Datetime standardCutoff = retentionTime.addDays(-30);
        Datetime errorCutoff = retentionTime.addDays(-180);

        List<FB_Integration_Log__c> logs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                CreatedDate < :standardCutoff
                AND (Level__c = null OR Level__c != 'ERROR')
            )
            OR (
                CreatedDate < :errorCutoff
                AND Level__c = 'ERROR'
            )
            LIMIT :probeSize
        ];

        if (logs.size() <= availableDmlRows) {
            // Complete smaller purges within the scheduled transaction.
            if (!logs.isEmpty()) {
                delete logs;
            }
        } else {
            // Process larger purges without exceeding transaction limits.
            Database.executeBatch(this, 200);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        if (retentionTime == null) {
            retentionTime = System.now();
        }

        Datetime standardCutoff = retentionTime.addDays(-30);
        Datetime errorCutoff = retentionTime.addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                CreatedDate < :standardCutoff
                AND (Level__c = null OR Level__c != 'ERROR')
            )
            OR (
                CreatedDate < :errorCutoff
                AND Level__c = 'ERROR'
            )
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<SObject> scope
    ) {
        delete scope;
    }

    public void finish(Database.BatchableContext context) {
    }

    public static Id scheduleNightly() {
        // The scheduling user's time zone determines the execution time.
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
