// Integrity checks must include Contacts the running user cannot see.
// No queried record details are exposed in the error message.
public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(triggerNew, null);
    }

    public void beforeUpdate(
        List<SObject> triggerNew,
        List<SObject> triggerOld
    ) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (SObject oldRecord : triggerOld) {
            Contact oldContact = (Contact) oldRecord;
            oldById.put(oldContact.Id, oldContact);
        }
        validate(triggerNew, oldById);
    }

    private static void validate(
        List<SObject> triggerNew,
        Map<Id, Contact> oldById
    ) {
        List<Contact> candidates = new List<Contact>();
        List<String> newKeys = new List<String>();
        List<String> oldKeys = new List<String>();

        Set<Id> changingIds = new Set<Id>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (SObject newRecord : triggerNew) {
            Contact current = (Contact) newRecord;

            // Already-failed updates retain their stored keys. Their IDs
            // are deliberately not included in changingIds.
            if (current.hasErrors()) {
                continue;
            }

            Contact previous = oldById == null
                ? null
                : oldById.get(current.Id);

            if (
                previous != null &&
                previous.AccountId == current.AccountId &&
                sameEmailValue(previous.Email, current.Email)
            ) {
                continue;
            }

            String newKey = keyFor(current);
            candidates.add(current);
            newKeys.add(newKey);
            oldKeys.add(keyFor(previous));

            // Include changes that clear AccountId or Email: they vacate
            // their old key even though their new value needs no checking.
            if (current.Id != null) {
                changingIds.add(current.Id);
            }

            if (newKey != null) {
                accountIds.add(current.AccountId);
                emails.add(current.Email.toLowerCase());
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Set<String> blockedKeys = new Set<String>();

        // Standard Email SOQL comparisons are case-insensitive. The
        // composite key below also normalizes case for in-memory checks.
        // This is the action's only SOQL query.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email IN :emails
        ]) {
            // Evaluate changing records using their proposed values,
            // rather than their stored values. This also excludes self.
            if (!changingIds.contains(existing.Id)) {
                blockedKeys.add(keyFor(existing));
            }
        }

        Set<Integer> rejectedIndexes = new Set<Integer>();
        Boolean addedRejection;

        // A rejected update keeps its OLD values during a partial save.
        // Restore those keys and propagate conflicts before returning,
        // rather than depending on repeated platform retries.
        do {
            addedRejection = false;
            Set<String> claimedKeys = new Set<String>();
            claimedKeys.addAll(blockedKeys);

            // Candidate order is the original trigger-list order.
            for (Integer i = 0; i < candidates.size(); i++) {
                if (
                    rejectedIndexes.contains(i) ||
                    newKeys[i] == null
                ) {
                    continue;
                }

                if (claimedKeys.contains(newKeys[i])) {
                    rejectedIndexes.add(i);
                    addedRejection = true;

                    if (oldKeys[i] != null) {
                        blockedKeys.add(oldKeys[i]);
                        claimedKeys.add(oldKeys[i]);
                    }
                } else {
                    claimedKeys.add(newKeys[i]);
                }
            }
        } while (addedRejection);

        for (Integer i = 0; i < candidates.size(); i++) {
            if (rejectedIndexes.contains(i)) {
                candidates[i].addError(ERROR_MESSAGE);
            }
        }
    }

    private static String keyFor(Contact record) {
        if (
            record == null ||
            record.AccountId == null ||
            String.isBlank(record.Email)
        ) {
            return null;
        }

        return String.valueOf(record.AccountId) +
            '|' +
            record.Email.toLowerCase();
    }

    private static Boolean sameEmailValue(String oldEmail, String newEmail) {
        if (oldEmail == null) {
            return newEmail == null;
        }

        // String.equals is case-sensitive, so a case-only edit is still
        // recognized as a field change. Uniqueness itself ignores case.
        return oldEmail.equals(newEmail);
    }
}
