/**
 * Maintains the org-wide open Case count on affected Accounts.
 * Intentionally runs without sharing and in system mode: the stored count must
 * include all Cases, regardless of the initiating user's record access or FLS.
 */
public without sharing class TA_Case_RollupOpenCount implements
    TriggerAction.AfterInsert,
    TriggerAction.AfterUpdate,
    TriggerAction.AfterDelete,
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldCasesById = new Map<Id, Case>();
        for (SObject record : triggerOld) {
            Case oldCase = (Case) record;
            oldCasesById.put(oldCase.Id, oldCase);
        }

        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case newCase = (Case) record;
            Case oldCase = oldCasesById.get(newCase.Id);

            if (newCase.AccountId != oldCase.AccountId ||
                newCase.IsClosed != oldCase.IsClosed) {
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
            }
        }

        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(collectAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(collectAccountIds(triggerNew));
    }

    private static Set<Id> collectAccountIds(List<SObject> records) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : records) {
            Case caseRecord = (Case) record;
            if (caseRecord.AccountId != null) {
                accountIds.add(caseRecord.AccountId);
            }
        }
        return accountIds;
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Lock parents before counting to serialize concurrent rollup writers.
        // Only live Accounts are returned; deleted parents need no update.
        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ];
        if (accounts.isEmpty()) {
            return;
        }

        Set<Id> liveAccountIds = new Set<Id>();
        Map<Id, Integer> countsByAccount = new Map<Id, Integer>();
        for (Account parent : accounts) {
            liveAccountIds.add(parent.Id);
            // An aggregate query omits parents with no matching Cases.
            countsByAccount.put(parent.Id, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :liveAccountIds
                AND IsClosed = false
            GROUP BY AccountId
        ]) {
            countsByAccount.put(
                (Id) result.get('AccountId'),
                (Integer) result.get('openCount')
            );
        }

        List<Account> updates = new List<Account>();
        for (Account parent : accounts) {
            Decimal desiredCount = countsByAccount.get(parent.Id);
            if (parent.FB_Open_Case_Count__c != desiredCount) {
                updates.add(new Account(
                    Id = parent.Id,
                    FB_Open_Case_Count__c = desiredCount
                ));
            }
        }

        if (!updates.isEmpty()) {
            // All-or-none: a failed rollup must also roll back the Case change.
            update updates;
        }
    }
}
