public with sharing class TA_Opportunity_LogAmountChange
    implements TriggerAction.AfterUpdate {

    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();
        Set<Id> pendingOpportunityIds = new Set<Id>();

        for (SObject record : triggerNew) {
            Opportunity current = (Opportunity) record;
            Opportunity previous = (Opportunity) oldById.get(current.Id);

            // Decimal comparison also detects changes to or from null.
            if (current.Amount != previous.Amount
                && !auditedOpportunityIds.contains(current.Id)) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = current.Id,
                    Status = 'Completed'
                ));
                pendingOpportunityIds.add(current.Id);
            }
        }

        if (tasksToInsert.isEmpty()) {
            return;
        }

        // Reserve IDs before DML to prevent duplicates from re-entry through
        // Task automation or the subsequent Opportunity rounding update.
        auditedOpportunityIds.addAll(pendingOpportunityIds);

        try {
            // Mandatory audit automation intentionally uses system-mode DML.
            insert tasksToInsert;
        } catch (DmlException ex) {
            auditedOpportunityIds.removeAll(pendingOpportunityIds);
            // The Opportunity change must not succeed without its audit.
            throw ex;
        }
    }
}
